var questions_default = {
	"past-2022-01": "这题我建议先在草稿纸上画表。横着三个时间，竖着三个因素，空着也没关系，画出来以后人、物、场就不会漏。",
	"past-2022-02": "饥饿把生长压慢，条件改善后出现追赶。若发生在胎儿期和两岁前，按 DOHaD 的说法，成年后的代谢风险也可能被改写。",
	"past-2022-03": "戒烟题别只写劝。先让学校觉得必须改（解冻），再落实课程、同伴支持、戒烟小组和无烟环境（改变），最后用制度、巡查和评价固定下来（再冻结）。",
	"past-2022-04": "哮喘先写遗传底子，再写环境诱因。过敏体质、气道高反应是底子，病毒感染、过敏原、空气污染和气候变化是点火的东西。",
	"past-2022-05": "四条曲线分开记：一般型跟身高体重走，神经型6岁前冲完，淋巴型12岁到两倍再退，生殖型青春期才启动。",
	"past-2022-06": "百分位法就是把同年龄同性别的孩子从矮到高排队，看他站在第几百分位。直观，但只能说现在的位置，不能直接说长得多快。",
	"past-2023-01": "英文题先把四个词写对：general、neural、lymphoid、genital。neural 只有一个突增期，lymphoid 会超过成人再退。",
	"past-2023-02": "catch-up growth 是暂时落后后的加速追赶。年龄越小通常越明显，但追得太快也可能有代谢代价。",
	"past-2023-03": "还是解冻、改变、再冻结。先让学校觉得非改不可，再落课程、同伴支持和无烟环境，最后把制度、巡查、奖励和评价钉住。只劝个人不算组织改变。",
	"past-2023-04": "主要健康问题答题时按类抓：营养、视力、心理、伤害、慢性病、传染病、特殊群体。特殊群体最容易被漏。",
	"past-2023-05": "疲劳是身体状态，疲倦是主观感受，过劳是长期积累。题目问临界指标，选早期疲劳。",
	"past-2023-06": "饥荒年代的胎儿会调整代谢，出生后如果突然高油高糖，原来的适应反而增加肥胖和代谢病风险。所以预防要看孕前、孕期和两岁前。",
	"past-2023-07": "比较两校身高，先同性别同年龄分层，再算均值、Z 分或百分位，最后比较分布。直接上 t 检验，前面该做的描述就漏了。",
	"past-2024-01": "puberty 是过程，puberty timing 是这个过程什么时候开始、按什么顺序发生。英文题问 timing，答案里要有时间模式。",
	"past-2024-02": "可以写成三层：基因给易感底子，环境负责触发，个体因素（肥胖、气道高反应等）再加一把。三层都写，答案就完整。",
	"past-2024-03": "案例题先看安全，再看风险。情绪问题、家庭变化、被忽视感可能叠在一起，划痕是信号，不要只用“叛逆”解释。必要时转介。",
	"past-2024-04": "还是解冻、改变、再冻结。冻结阶段要写制度、巡查、奖励和评价，别只写一次讲座。",
	"past-2024-05": "肥胖环境包括高热量食物、含糖饮料、屏幕时间、久坐、缺觉，还有家庭和学校周边。表现不只看体重，腰围、代谢和心理也要看。",
	"past-2024-06": "可塑性是轨迹能被环境和干预改变，但不是无限回弹。越早干预通常越有利，窗口过去后代价更大。",
	"quiz1-01": "青春期是第二次突增，不是最快。最快在胎儿期到1岁末，题干问“最快”，别被青春期带走。",
	"quiz1-02": "动作发育先近躯干、先大动作，先抬头后翻身。这题按课件选 E，但同卷另一题又把“精细动作早于大动作”列进反馈，题库本身有矛盾，页面上已标疑点。",
	"quiz1-03": "看到“围”就想横向。腰围是绕一圈，身高、坐高、顶臀长都是纵向。",
	"quiz1-04": "脑是神经型，6岁前冲完；胸腺是淋巴型，12岁到两倍再退；卵巢和生殖系统等青春期。",
	"quiz1-05": "不会交流、兴趣窄、重复摆鞋和转轮子，再加听力发声正常，这条线指向孤独症。ADHD 的关键是注意缺陷和多动冲动。",
	"quiz1-06": "气质比例别只背 40。平易 40%，中间 35%，缓慢 15%，困难 10%。困难型最少。",
	"quiz1-07": "男孩第二性征通常阴毛、腋毛、胡须；遗精是生殖功能开始成熟的标志。",
	"quiz1-08": "胸腺生后头10年长得快，12岁到成人约200%，之后萎缩。看到胸腺就想到淋巴型。",
	"quiz1-09": "握力、心率、肺活量是身体在工作；胸围、上肢长只是量外形。",
	"quiz1-10": "内胚圆、中胚壮、外胚瘦。这题选项里没有中胚型，但三种体型本身要记住。",
	"quiz1-11": "外胚层瘦长，神经和感觉器官发达；圆胖是内胚，骨骼肌肉发达是中胚。",
	"quiz1-12": "青春期启动可以记成中枢抑制减弱，加上 HPG 轴对性激素负反馈不那么敏感。",
	"quiz1-13": "情绪障碍是焦虑、抑郁、强迫、恐怖。孤独症是神经发育障碍，不塞进这个篮子。",
	"quiz1-14": "近侧先、头尾先、大动作先。先抬头后翻身，所以“先翻身”错。",
	"quiz1-15": "大脑加速期在胎儿末三个月到出生后两年。青春期再冲的是身体和生殖系统。",
	"quiz1-16": "出生时只看清约19厘米，6个月前是视力敏感期，4个月左右开始辨色。",
	"quiz1-17": "2岁主要靠无意注意，哪里响看哪里。有意注意是后来慢慢发展的。",
	"quiz1-18": "学习困难是某一科或某类能力卡住，不等于整体智商低。",
	"quiz1-19": "这题答案取“错”。门诊男孩更常见，但女童 ADHD 也可能被低估，题目说法本身有争议。",
	"quiz1-20": "女孩通常乳房先发育，阴毛腋毛随后。初潮是重要节点，但不是第一声发令枪。",
	"quiz2-02": "答案取 A、B。但体育锻炼也影响代谢和心理行为，别因为题目只给了两个选项就以为它只管身体。",
	"quiz2-03": "纵向是跟同一批人很多年，能看到速度，但费时费钱、容易失访。说它花费小就错了。",
	"quiz2-04": "现状正常值是现在这群人的水平，理想正常值参考潜力较好的人，通常更高。题干说反了。",
	"quiz2-05": "全国学生体质调研是同一时间对不同年龄一起调查，属于横断面，不是纵向。",
	"quiz2-06": "沙眼已经基本控制。现在更常见的是近视、肥胖、脊柱弯曲、龋齿这些。",
	"quiz2-07": "哮喘怕过敏原、病毒、气候变化和脏空气。清洁空气是保护因素。",
	"quiz2-08": "游泳是运动。闯红灯、不吃早餐、吸烟、游戏成瘾才是健康危险行为。",
	"quiz2-09": "DOHaD 主要盯胎儿和婴幼儿期。早期营养和不良暴露，会影响成年后的慢性病风险。",
	"quiz2-11": "一线筛查先目测、身高体重、BMI、腰围。双能X线是体成分测定，不是常规筛查第一步。",
	"quiz2-12": "主要健康问题按五类抓：近视、肥胖、营养不足、心理行为、传染病。",
	"quiz2-13": "近视三个屈光参数：眼轴、角膜屈光力、晶状体屈光力。睫状肌和眼球壁不算这三项。",
	"quiz2-14": "调查应用可以记五件事：描述水平、反映动态、评价队列、制定标准、评价干预。",
	"quiz2-15": "水平评价常用离差、百分位、Z 分。第二性征年龄和骨龄是发育年龄，不是水平评价。",
	"quiz2-16": "家庭环境包括经济、父母教育、亲子关系、家庭结构。学校环境是另一类。",
	"quiz2-17": "遗传给潜能，环境给现实。题干说反了。",
	"quiz2-18": "长期上网会挤掉睡眠、运动和面对面交流，还可能带来视屏和心理问题，不能说无害。",
	"quiz2-19": "身体健康是基础，但健康还包括心理、社会适应和道德。基础不等于全部。",
	"quiz2-20": "这题答案取“错”。窝沟封闭是预防窝沟龋的重要措施，但课程没有把它说成唯一关键途径。",
	"quiz2-21": "单项上等只说明这一项好，不代表整体发育都好。一门高分不等于全科都好。",
	"quiz2-22": "每学期查两次视力是面向全体学生的策略。高危管理和患者管理是另外两层。",
	"quiz3-01": "近视会影响看路况、判断距离和反应速度，所以和意外伤害有关。说没影响是错的。",
	"quiz3-02": "意外伤害的关键是主观上没想让它发生。校园暴力是有人故意为之，分界线在意图。",
	"quiz3-03": "把家具棱角磨圆，改的是环境，不是人的行为，所以属于工程策略。",
	"quiz3-04": "照度均匀度不低于0.7，是最暗处不能低于最亮处的七成。别记成0.5。",
	"quiz3-05": "一节数学一节语文轮着上，让不同脑区轮流兴奋和休息，这是镶嵌式活动。",
	"quiz3-06": "题目问临界指标，选早期疲劳。再往后才是显著疲劳和过劳。",
	"quiz3-07": "早期疲劳先坐不住、听不进；逻辑思维和记忆力明显下降，说明已经更深了。",
	"quiz3-08": "投射角20°～22°看窗上缘，开角4°～5°看窗外遮挡物。一个抬头看窗顶，一个从窗顶再往外看。",
	"quiz3-09": "开角只要4°～5°，它量的是窗上缘和对面遮挡物之间那道缝。别和投射角混。",
	"quiz3-10": "看黑板上缘，视线和黑板面的夹角不低于45°。角度太小，前排要仰头。",
	"quiz3-11": "椅座距离最合适是4厘米以内的负距离，椅座前缘轻轻探到桌沿下面，但不能太深。",
	"quiz3-12": "桌椅高差按坐高的三分之一。三份坐高，一份高差。",
	"quiz3-13": "国内学校最常用的是课堂讲授。看到“最普遍采用的传播方法”，先选它。",
	"quiz3-14": "讲座偏单向，学生没动起来。参与式要同伴教育、角色扮演、小组讨论、头脑风暴这类方法。",
	"quiz3-15": "大众媒体隔着屏幕，不需要面对面，所以是间接方法。",
	"quiz3-16": "群体运动密度不低于75%，就是一节课至少四分之三的时间学生在动，不是排队看别人练。",
	"quiz3-17": "有智力障碍或神经系统疾病的儿童，遭受虐待和忽视的风险更高。题干说“不容易”，方向反了。",
	"quiz3-19": "标本室是存放标本，不是培养标本，不需要阳光直射。需要采光的是教室和实验室。",
	"quiz3-20": "把灯降低会让光源更刺眼，不是控制眩光。漫射、遮光、不用裸灯、灯管长轴垂直黑板才是办法。",
	"quiz3-21": "意外伤害常见交通、跌落、溺水、烧伤。自伤是故意伤害，不能混进意外。",
	"quiz3-22": "流行特点抓大龄、低社会地位家庭风险高、男孩高于女孩、总体上升。C项讲的是别的国家的自杀率比较，不属于本题。",
	"quiz3-23": "Haddon 三因素是宿主、媒介物、环境，也就是人、物、场。社会不是单独一因素，预防措施是后面填的内容。",
	"quiz3-24": "自杀前可能出现紧张、抑郁、失望、易怒、担忧，五个都算。别只勾抑郁。",
	"quiz3-25": "网络暴力的危害会落到个人权利、社会秩序、法律和道德，五个选项都算。",
	"quiz3-26": "网络暴力的流行特征可以抓群体性、情绪化、盲目、从众、跨地域和个体避责。人在群里，责任容易被摊薄。",
	"quiz3-27": "学校健康教育不只讲洗手。行为生活方式、疾病预防、安全应急、生长发育与青春期、心理健康，五块都要。",
	"quiz3-28": "学校要远离污染源、市场和娱乐场所，但靠近科技文化体育设施通常是加分项。D项说反了。",
	"quiz3-29": "电脑姿势记手腕直、键盘正、鼠标后位坐姿、肩放松、肘膝约90°。本题答案取 B、C、D、E，A的头颈距离与课件口径不一致。",
	"quiz3-30": "大脑皮质五个特性：始动调节、优势法则、动力定型、保护性抑制、终末激发。按一天的学习过程串起来。"
};
